from taf.ul.trs_e2e_fw.lib.ems.nom.nom_base import NomBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class OtherNomOps(NomBase):

    def __init__(self):
        super(OtherNomOps, self).__init__()
        self.bts_moc_id = 'PLMN-PLMN/MRBTS-{bts_id}'.format(bts_id=get_config_variable(['bts_id']))

    def delete_object_from_monitor(self, **kwargs):
        """ Delete object from monitor """

        conf_id = kwargs.pop("conf_id", 1)
        dist_names = kwargs["dist_names"]
        return self.nom_factory.nom.delete_managed_objects(conf_id=conf_id, mo_ids=dist_names)
